<?php require_once __DIR__.'/../includes/bootstrap.php';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$email=strtolower(trim($_POST['email']??''));$generic='If that address belongs to an account, reset instructions are available.';if(filter_var($email,FILTER_VALIDATE_EMAIL)){if(!rate_limited('reset:'.$email,5,60)){log_attempt('reset:'.$email,false);$q=db()->prepare('SELECT id FROM users WHERE email=?');$q->execute([$email]);if($u=$q->fetch()){$token=bin2hex(random_bytes(32));$hash=hash('sha256',$token);$q=db()->prepare('INSERT INTO password_reset_tokens(user_id,token_hash,expires_at) VALUES(?,?,UTC_TIMESTAMP()+INTERVAL 30 MINUTE)');$q->execute([$u['id'],$hash]);if(getenv('APP_ENV')==='local'){$url=(getenv('APP_URL')?:'http://localhost:8000').'/reset-password.php?token='.urlencode($token);$file=__DIR__.'/../var/reset-links.log';file_put_contents($file,date('c').' '.$url.PHP_EOL,FILE_APPEND|LOCK_EX);chmod($file,0600);}else{error_log('Password reset email delivery is not configured; request retained but no link was sent.');}}}}flash('success',$generic);redirect('/forgot-password.php');}
render_start('Reset your password');?><p class="lede">Enter your account email. Locally, a reset link is written to the private <code>var/reset-links.log</code> file.</p><form method="post"><?=csrf_field()?><label>Email<input type="email" name="email" autocomplete="email" required></label><button class="button">Request reset link</button></form><p class="below"><a href="/login.php">Return to sign in</a></p><?php render_end();
